 if(!state||!project)return <div className="loading"><img src="./brand.png"/><h1>HELLRASHER MUSIC GENERATOR</h1><p>{error||'Otevírání lokálního pracovního prostoru…'}</p></div>;
 const variants:Variant[]=state.variants,projectVariants=variants.filter(v=>v.projectId===project.id),gpu=state.gpu[0],prompt=caption(project),activeJob=state.jobs.find((j:any)=>j.id===state.activeJob),defaults=state.engine.defaults||{},queueJobs=state.jobs.filter((j:any)=>['queued','running'].includes(j.status)),totalBytes=state.models.entries.reduce((n:number,e:any)=>n+e.bytes,0);
