 {!project.closedPanels.includes('style')&&<Panel id="style" title="Hudební styl a popis" subtitle="Libovolný žánr. Libovolná kombinace." icon={Sparkles} onClose={closePanel}>{field('concept','Co chcete vytvořit?','Popište hudbu česky nebo anglicky: styl, hlas, nástroje, náladu a vývoj skladby.',true,'Lokální AI připraví anglické hudební zadání. Původní popis a vlastní text zůstávají uložené.')}<div className="field"><span>VAŠE HUDEBNÍ STYLY</span><div className="selected-styles">{project.styles.map((s,i)=><div className="style-token" key={i}><span>{i===0?'HLAVNÍ':'VEDLEJŠÍ'}</span><strong>{s.name}</strong>{project.advanced&&<select aria-label={`Důraz stylu ${s.name}`} value={s.weight} onChange={e=>change('styles',project.styles.map((x,j)=>i===j?{...x,weight:e.target.value}:x))}><option value="">Dle zadání</option><option value="subtle">Jemný důraz</option><option value="balanced">Vyvážený důraz</option><option value="strong">Silný důraz</option></select>}{i>0&&<button className="icon" title="Nastavit jako hlavní styl" onClick={()=>change('styles',[s,...project.styles.filter((_,j)=>j!==i)])}><ArrowUp size={13}/></button>}<button className="icon" title="Odebrat styl" onClick={()=>change('styles',project.styles.filter((_,j)=>j!==i))}><X size={13}/></button></div>)}{!project.styles.length&&<p className="muted small">Vyberte styl nebo popište vlastní koncept.</p>}</div></div><div className="input-action"><input aria-label="Vlastní styl" placeholder="Vlastní žánr nebo hudební koncept…" value={customGenre} onChange={e=>setCustomGenre(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&customGenre.trim()){change('styles',[...project.styles,{name:customGenre.trim(),weight:''}]);setCustomGenre('');}}}/><button className="secondary" disabled={!customGenre.trim()} onClick={()=>{change('styles',[...project.styles,{name:customGenre.trim(),weight:''}]);setCustomGenre('');}}><Plus size={15}/></button></div><details className="catalog"><summary>Procházet katalog stylů <ChevronRight size={14}/></summary><div className="search-box"><Search size={15}/><input aria-label="Hledat hudební styl" placeholder="Vyhledat žánr…" value={genreSearch} onChange={e=>setGenreSearch(e.target.value)}/></div><div className="genre-catalog">{Object.entries(GENRES).map(([category,items])=>{const matches=items.filter((x:string)=>x.toLowerCase().includes(genreSearch.toLowerCase()));return matches.length>0&&<div key={category}><small>{category}</small><div className="chips">{matches.map((g:string)=><button key={g} className={'chip '+(project.styles.some(s=>s.name===g)?'selected':'')} onClick={()=>{if(!project.styles.some(s=>s.name===g))change('styles',[...project.styles,{name:g,weight:''}]);}}>{g}</button>)}</div></div>;})}</div></details>{project.advanced&&<><div className="form-grid"><Field label="Tempo BPM"><input type="number" min="0" max="400" value={project.bpm||''} placeholder="Dle zadání" onChange={e=>change('bpm',+e.target.value)}/></Field>{field('key','Tónina','Např. D')}{field('scale','Stupnice','Např. minor')}{field('meter','Takt','Např. 4/4')}</div><div className="form-grid">{field('mood','Nálada / emoční vývoj','Warm, hopeful, gradually uplifting')}{field('energy','Energie a dynamika','Restrained opening, powerful finale')}{field('scenario','Poslechový kontext','Live concert, late night listening…')}{field('production','Produkční charakter','Natural, modern, vintage…')}{field('space','Zvukový prostor','Intimate room, wide stereo…')}{field('groove','Groove a rytmus','Swing, syncopated, four-on-the-floor…')}</div><div className="note"><Info size={14}/> BPM, tónina, váhy stylů a aranžmá jsou generativní instrukce. Model nezaručuje jejich přesné dodržení.</div></>}</Panel>}
